import{_ as h,o as n,c as i,a2 as s}from"./chunks/framework.BBd5PKnH.js";const a="/dev-notes/assets/03-natal-chart-whole-sign.Du3M6YQD.svg",o="/dev-notes/assets/02-whole-sign-cusps.BExxUBPV.svg",d="data:image/svg+xml;base64,",c="/dev-notes/assets/04-aspect-from-sagittarius.DIOQsEJo.svg",e="/dev-notes/assets/05-aspect-sign-vs-orb.CMaFfW8y.svg",y=JSON.parse('{"title":"Note 8: House system (whole sign vs Placidus) và Aspect","description":"","frontmatter":{},"headers":[],"relativePath":"astro/houses/house-systems-and-aspects.md","filePath":"astro/houses/house-systems-and-aspects.md"}'),r={name:"astro/houses/house-systems-and-aspects.md"};function g(u,t,l,I,m,b){return n(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="note-8-house-system-whole-sign-vs-placidus-va-aspect" tabindex="-1">Note 8: House system (whole sign vs Placidus) và Aspect <a class="header-anchor" href="#note-8-house-system-whole-sign-vs-placidus-va-aspect" aria-label="Permalink to &quot;Note 8: House system (whole sign vs Placidus) và Aspect&quot;">​</a></h1><blockquote><p><strong>[Sách]</strong> = có trong các trang sách đã đọc. <strong>[Bổ sung]</strong> = kiến thức traditional astrology nói chung, nên đối chiếu khi sách dạy tới. Các hình nằm trong thư mục <code>images/</code>. Độ của Asc, MC, Dsc, IC trong hình là <strong>ước lượng từ ảnh phần mềm</strong>, không phải số chính xác.</p></blockquote><hr><h2 id="tom-tat-nhanh" tabindex="-1">Tóm tắt nhanh <a class="header-anchor" href="#tom-tat-nhanh" aria-label="Permalink to &quot;Tóm tắt nhanh&quot;">​</a></h2><ol><li><strong>Cusp</strong> = điểm bắt đầu của một house. Whole sign: cusp luôn là 0° của một sign. Placidus: cusp nằm ở những độ lẻ.</li><li>Cùng một lá số, hai hệ cho <strong>house khác nhau</strong>, nên chủ đề đọc ra khác nhau.</li><li><strong>Aspect giữa hai hành tinh không phụ thuộc hệ house.</strong> Nhưng có hai cách tính aspe◊◊ct: theo sign và theo độ (orb).</li><li>Mặc định trong các note này: <strong>whole sign</strong>, vì sách của Demetra George dùng whole sign.</li></ol><hr><h2 id="_1-la-so-vi-du-viet-lai-theo-whole-sign" tabindex="-1">1. Lá số ví dụ (viết lại theo whole sign) <a class="header-anchor" href="#_1-la-so-vi-du-viet-lai-theo-whole-sign" aria-label="Permalink to &quot;1. Lá số ví dụ (viết lại theo whole sign)&quot;">​</a></h2><p>Asc ≈ 26° Libra, nên <strong>Libra là house 1</strong>. Chart ruler là Venus. Sun nằm dưới đường chân trời nên đây là <strong>lá số đêm</strong>.</p><p><img src="'+a+'" alt="Lá số ví dụ theo whole sign"></p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Sign và độ</th><th>House (phần mềm, Placidus)</th><th>House (whole sign)</th><th>Phe</th></tr></thead><tbody><tr><td>Sun</td><td>3° Aquarius</td><td>4</td><td><strong>5</strong></td><td>Trái phe</td></tr><tr><td>Moon</td><td>11° Libra</td><td>12</td><td><strong>1</strong></td><td>Đúng phe</td></tr><tr><td>Mercury</td><td>12° Capricorn</td><td>3</td><td><strong>4</strong></td><td>Trái phe (mọc trước Sun 21° nên theo phe ngày)</td></tr><tr><td>Venus</td><td>17° Sagittarius</td><td>2</td><td><strong>3</strong></td><td>Đúng phe</td></tr><tr><td>Mars</td><td>4° Sagittarius</td><td>2</td><td><strong>3</strong></td><td>Đúng phe</td></tr><tr><td>Jupiter (Rx)</td><td>14° Leo</td><td>10</td><td><strong>11</strong></td><td>Trái phe</td></tr><tr><td>Saturn (Rx)</td><td>23° Gemini</td><td>8</td><td><strong>9</strong></td><td>Trái phe</td></tr></tbody></table><p>Uranus, Neptune, Pluto bỏ qua theo cách đọc cổ điển.</p><hr><h2 id="_2-cusp-la-gi" tabindex="-1">2. Cusp là gì <a class="header-anchor" href="#_2-cusp-la-gi" aria-label="Permalink to &quot;2. Cusp là gì&quot;">​</a></h2><p>Cusp nghĩa đen là &quot;đỉnh, mũi nhọn&quot;, ở đây là <strong>điểm bắt đầu của một house</strong>.</p><table tabindex="0"><thead><tr><th></th><th>Placidus (và các hệ quadrant)</th><th>Whole sign</th></tr></thead><tbody><tr><td>Cusp nằm ở đâu</td><td>Một độ cụ thể tính từ giờ và nơi sinh (ví dụ 17° Gemini)</td><td>Luôn là <strong>0° của một sign</strong></td></tr><tr><td>Độ lớn mỗi house</td><td>Không đều nhau</td><td>Đúng 30°</td></tr><tr><td>Cusp của house 1</td><td>Chính là độ của Asc</td><td><strong>Không phải Asc</strong>, mà là 0° của sign chứa Asc</td></tr></tbody></table><p><img src="'+o+'" alt="Whole sign: cusp và các góc"></p><p><strong>Điều dễ nhầm:</strong> trong whole sign, Asc, MC, Dsc, IC vẫn có độ riêng, nhưng chúng <strong>nằm bên trong house</strong>, không phải cusp. Ví dụ Asc ≈ 26° Libra nằm trong house 1 (cusp của house 1 là 0° Libra).</p><p>Khi gửi bảng cho người khác đọc, bạn không cần cột cusp kiểu Placidus. Chỉ cần <strong>cung của Asc</strong> (và độ của các góc nếu muốn xếp hành tinh angular nhất).</p><hr><h2 id="_3-whole-sign-va-placidus-cho-ket-qua-khac-nhau" tabindex="-1">3. Whole sign và Placidus cho kết quả khác nhau <a class="header-anchor" href="#_3-whole-sign-va-placidus-cho-ket-qua-khac-nhau" aria-label="Permalink to &quot;3. Whole sign và Placidus cho kết quả khác nhau&quot;">​</a></h2><p><img src="'+d+'" alt="Moon: whole sign và Placidus"></p><p>Moon ở 11° Libra nằm trước điểm Asc khoảng 15°:</p><ul><li>Whole sign: cùng sign Libra với Asc, nên <strong>house 1</strong>.</li><li>Placidus: nằm trước Asc, nên <strong>house 12</strong>.</li></ul><h3 id="chu-đe-đoc-ra-khac-han" tabindex="-1">Chủ đề đọc ra khác hẳn <a class="header-anchor" href="#chu-đe-đoc-ra-khac-han" aria-label="Permalink to &quot;Chủ đề đọc ra khác hẳn&quot;">​</a></h3><p>Chủ đề house lấy theo danh sách trong sách:</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Placidus</th><th>Whole sign</th></tr></thead><tbody><tr><td>Moon</td><td>House 12 (khó khăn, ẩn giấu)</td><td>House 1 (bản thân, sinh lực)</td></tr><tr><td>Sun</td><td>House 4 (cha mẹ, gốc gác)</td><td>House 5 (con cái, vui chơi)</td></tr><tr><td>Venus, Mars</td><td>House 2 (tiền bạc)</td><td>House 3 (anh chị em, đi lại)</td></tr><tr><td>Saturn</td><td>House 8 (cái chết, tài sản chung)</td><td>House 9 (tôn giáo, du hành xa)</td></tr><tr><td>Jupiter</td><td>House 10 (sự nghiệp)</td><td>House 11 (bạn bè, hy vọng)</td></tr></tbody></table><h3 id="he-nao-đung" tabindex="-1">Hệ nào đúng? <a class="header-anchor" href="#he-nao-đung" aria-label="Permalink to &quot;Hệ nào đúng?&quot;">​</a></h3><p>Không có thực nghiệm phân định. Hai hệ đi kèm hai cách đọc khác nhau:</p><ul><li><strong>Whole sign</strong>: theo mình biết là hệ cổ nhất, gắn với chiêm tinh Hellenistic. Khớp với toàn bộ kỹ thuật cổ điển (ruler theo sign, aspect theo sign, joy). Ví dụ Maria von Trapp trong sách chỉ khớp với whole sign.</li><li><strong>Placidus</strong>: xuất hiện muộn hơn, phổ biến trong chiêm tinh hiện đại và nhiều phần mềm mặc định.</li><li>Phần lịch sử này mình không chắc chi tiết, bạn nên kiểm tra thêm.</li></ul><h3 id="neu-lam-noi-dung-thuong-mai" tabindex="-1">Nếu làm nội dung thương mại <a class="header-anchor" href="#neu-lam-noi-dung-thuong-mai" aria-label="Permalink to &quot;Nếu làm nội dung thương mại&quot;">​</a></h3><ul><li>Chọn một hệ làm hệ chính và <strong>nói rõ</strong> (ví dụ &quot;mình dùng whole sign houses&quot;).</li><li>Đừng trộn hai hệ trong cùng một lá số.</li><li>Với hành tinh nằm gần ranh giới (như Moon ở trên), ghi chú rằng hệ khác có thể cho kết quả khác.</li></ul><hr><h2 id="_4-aspect-theo-whole-sign-nhin-thay-nhau" tabindex="-1">4. Aspect theo whole sign: &quot;nhìn thấy nhau&quot; <a class="header-anchor" href="#_4-aspect-theo-whole-sign-nhin-thay-nhau" aria-label="Permalink to &quot;4. Aspect theo whole sign: &quot;nhìn thấy nhau&quot;&quot;">​</a></h2><p>Theo whole sign, hai hành tinh có aspect hay không chỉ phụ thuộc vào <strong>số sign cách nhau</strong> (đếm theo chiều ngắn hơn):</p><table tabindex="0"><thead><tr><th>Cách nhau</th><th>Quan hệ</th><th>Nhìn thấy nhau?</th></tr></thead><tbody><tr><td>0 sign (cùng sign)</td><td>Hợp (conjunction)</td><td>Có</td></tr><tr><td>1 sign (ngay cạnh)</td><td>Không có aspect</td><td><strong>Không</strong></td></tr><tr><td>2 sign</td><td>Sextile (60°)</td><td>Có, hài hòa</td></tr><tr><td>3 sign</td><td>Square (90°)</td><td>Có, căng</td></tr><tr><td>4 sign</td><td>Trine (120°)</td><td>Có, hài hòa</td></tr><tr><td>5 sign</td><td>Không có aspect</td><td><strong>Không</strong></td></tr><tr><td>6 sign</td><td>Đối (opposition, 180°)</td><td>Có, căng</td></tr></tbody></table><p><img src="'+c+'" alt="Aspect nhìn từ Sagittarius"></p><p><strong>Điều dễ gây hiểu nhầm:</strong> sign ngay cạnh nhau lại <strong>không nhìn thấy nhau</strong>. Truyền thống gọi các sign này là &quot;quay mặt&quot; (averse). Trong chiêm tinh hiện đại hai kiểu này vẫn có tên (semi-sextile 30°, quincunx 150°), nhưng theo cách nói truyền thống mà mình biết thì chúng không phải aspect. Mình chưa chắc sách của Demetra George trình bày ra sao, bạn nên đối chiếu khi đọc tới.</p><h3 id="aspect-đay-đu-cua-la-so-vi-du-theo-sign-bo-sung" tabindex="-1">Aspect đầy đủ của lá số ví dụ (theo sign) [Bổ sung] <a class="header-anchor" href="#aspect-đay-đu-cua-la-so-vi-du-theo-sign-bo-sung" aria-label="Permalink to &quot;Aspect đầy đủ của lá số ví dụ (theo sign) [Bổ sung]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Hợp</th><th>Sextile</th><th>Square</th><th>Trine</th><th>Đối</th><th>Không thấy</th></tr></thead><tbody><tr><td>Sun</td><td></td><td>Venus, Mars</td><td></td><td>Moon, Saturn</td><td>Jupiter</td><td>Mercury</td></tr><tr><td>Moon</td><td></td><td>Venus, Mars, Jupiter</td><td>Mercury</td><td>Sun, Saturn</td><td></td><td></td></tr><tr><td>Mercury</td><td></td><td></td><td>Moon</td><td></td><td></td><td>Sun, Venus, Mars, Jupiter, Saturn</td></tr><tr><td>Venus</td><td>Mars</td><td>Sun, Moon</td><td></td><td>Jupiter</td><td>Saturn</td><td>Mercury</td></tr><tr><td>Mars</td><td>Venus</td><td>Sun, Moon</td><td></td><td>Jupiter</td><td>Saturn</td><td>Mercury</td></tr><tr><td>Jupiter</td><td></td><td>Moon, Saturn</td><td></td><td>Venus, Mars</td><td>Sun</td><td>Mercury</td></tr><tr><td>Saturn</td><td></td><td>Jupiter</td><td></td><td>Sun, Moon</td><td>Venus, Mars</td><td>Mercury</td></tr></tbody></table><p><strong>Nhận xét nhanh:</strong> Mercury gần như cô lập, chỉ thấy Moon (square). Moon nhận nhiều aspect nhất. Cụm Venus–Mars bị Saturn đối nhưng được Jupiter trine.</p><hr><h2 id="_5-aspect-co-đoi-theo-he-house-khong" tabindex="-1">5. Aspect có đổi theo hệ house không? <a class="header-anchor" href="#_5-aspect-co-đoi-theo-he-house-khong" aria-label="Permalink to &quot;5. Aspect có đổi theo hệ house không?&quot;">​</a></h2><p><strong>Không.</strong> Aspect chỉ phụ thuộc vị trí hai hành tinh trên vòng hoàng đạo.</p><table tabindex="0"><thead><tr><th>Không đổi theo hệ house</th><th>Đổi theo hệ house</th></tr></thead><tbody><tr><td>Aspect giữa hai hành tinh</td><td>Hành tinh ở house nào</td></tr><tr><td>Dignity, retrograde, khoảng cách tới Sun</td><td>Chủ house nào, house nào trống</td></tr><tr><td>Lá số ngày hay đêm (thường không đổi)</td><td>Hành tinh angular, succedent hay cadent theo house</td></tr><tr><td>Độ của Asc và MC</td><td>Cusp của các house giữa</td></tr></tbody></table><h3 id="nhung-co-hai-cach-tinh-aspect-đoc-lap-voi-he-house" tabindex="-1">Nhưng có hai cách tính aspect (độc lập với hệ house) <a class="header-anchor" href="#nhung-co-hai-cach-tinh-aspect-đoc-lap-voi-he-house" aria-label="Permalink to &quot;Nhưng có hai cách tính aspect (độc lập với hệ house)&quot;">​</a></h3><ul><li><strong>Theo sign</strong>: chỉ đếm số sign cách nhau, bỏ qua độ (cách ở mục 4).</li><li><strong>Theo độ và orb</strong>: tính hai hành tinh cách nhau bao nhiêu độ, xem có gần 60°, 90°, 120°, 180° trong một khoảng sai lệch (orb, thường khoảng 6 đến 10° tùy tác giả) hay không.</li></ul><p><img src="'+e+'" alt="Aspect theo sign và độ lệch thực tế"></p><p>Cùng lá số, theo sign có 16 aspect. Theo độ với orb ±8° (chỉ để minh họa) chỉ còn 8 aspect chặt. Ví dụ:</p><ul><li>Venus – Saturn (đối): lệch 6°, nằm trong orb.</li><li>Mars – Saturn (đối): lệch 19°, có aspect theo sign nhưng theo độ thì gần như không.</li><li>Sun – Saturn (trine): lệch 20°, cũng vậy.</li></ul><p>Aspect có ở <strong>cả hai cách</strong> là chắc nhất. Aspect chỉ có theo sign nên xem là yếu hơn, và nên ghi rõ đó là aspect theo sign. Mình chưa chắc sách của Demetra George có xét độ để phân mạnh yếu hay không, bạn hãy đối chiếu khi đọc tới.</p><hr><h2 id="_6-chu-house-va-co-nhin-thay-house-cua-minh-khong-bo-sung" tabindex="-1">6. Chủ house và &quot;có nhìn thấy house của mình không&quot; [Bổ sung] <a class="header-anchor" href="#_6-chu-house-va-co-nhin-thay-house-cua-minh-khong-bo-sung" aria-label="Permalink to &quot;6. Chủ house và &quot;có nhìn thấy house của mình không&quot; [Bổ sung]&quot;">​</a></h2><p>Theo cách đọc truyền thống: chủ house đứng ở đâu thì câu chuyện của house đó &quot;đi&quot; về đó. Và chủ house <strong>nhìn thấy</strong> house của mình (có aspect) thì kết nối chặt hơn, <strong>không nhìn thấy</strong> thì kết nối yếu hơn.</p><table tabindex="0"><thead><tr><th>House</th><th>Sign (chủ)</th><th>Chủ đang ở sign, house</th><th>Aspect chủ → house</th></tr></thead><tbody><tr><td>1</td><td>Libra (Venus)</td><td>Sagittarius, 3</td><td>Sextile, <strong>thấy</strong></td></tr><tr><td>2</td><td>Scorpio (Mars)</td><td>Sagittarius, 3</td><td>Cách 1 sign, <strong>không thấy</strong></td></tr><tr><td>3</td><td>Sagittarius (Jupiter)</td><td>Leo, 11</td><td>Trine, <strong>thấy</strong></td></tr><tr><td>4</td><td>Capricorn (Saturn)</td><td>Gemini, 9</td><td>Cách 5 sign, <strong>không thấy</strong></td></tr><tr><td>5</td><td>Aquarius (Saturn)</td><td>Gemini, 9</td><td>Trine, <strong>thấy</strong></td></tr><tr><td>6</td><td>Pisces (Jupiter)</td><td>Leo, 11</td><td>Cách 5 sign, <strong>không thấy</strong></td></tr><tr><td>7</td><td>Aries (Mars)</td><td>Sagittarius, 3</td><td>Trine, <strong>thấy</strong></td></tr><tr><td>8</td><td>Taurus (Venus)</td><td>Sagittarius, 3</td><td>Cách 5 sign, <strong>không thấy</strong></td></tr><tr><td>9</td><td>Gemini (Mercury)</td><td>Capricorn, 4</td><td>Cách 5 sign, <strong>không thấy</strong></td></tr><tr><td>10</td><td>Cancer (Moon)</td><td>Libra, 1</td><td>Square, <strong>thấy</strong></td></tr><tr><td>11</td><td>Leo (Sun)</td><td>Aquarius, 5</td><td>Đối, <strong>thấy</strong></td></tr><tr><td>12</td><td>Virgo (Mercury)</td><td>Capricorn, 4</td><td>Trine, <strong>thấy</strong></td></tr></tbody></table><p>&quot;Thấy&quot; chỉ nói có kết nối, chưa nói tốt hay xấu. Trine và sextile hài hòa, square và đối căng. Tốt hay xấu còn phụ thuộc condition của chủ house (đúng phe hay trái phe, dignity, phase...).</p><h3 id="nhung-đieu-can-sua-so-voi-cac-luot-đoc-truoc" tabindex="-1">Những điều cần sửa so với các lượt đọc trước <a class="header-anchor" href="#nhung-đieu-can-sua-so-voi-cac-luot-đoc-truoc" aria-label="Permalink to &quot;Những điều cần sửa so với các lượt đọc trước&quot;">​</a></h3><ul><li><strong>Sun sextile Venus và Mars</strong> trước đây bị thiếu, nay đã có trong bảng ở mục 4.</li><li><strong>Tiền bạc (house 2)</strong>: Mars là chủ house 2 nhưng không nhìn thấy house 2, nên kết nối yếu hơn mình từng nói &quot;khá thuận&quot;.</li><li><strong>Saturn và Mercury &quot;ở nhà của nhau&quot;</strong>: Capricorn và Gemini cách nhau 5 sign nên không nhìn thấy nhau. Sự &quot;đỡ nhau&quot; chỉ ở mức trên danh nghĩa.</li></ul><hr><h2 id="_7-checklist-khi-đoc-mot-la-so-theo-whole-sign" tabindex="-1">7. Checklist khi đọc một lá số theo whole sign <a class="header-anchor" href="#_7-checklist-khi-đoc-mot-la-so-theo-whole-sign" aria-label="Permalink to &quot;7. Checklist khi đọc một lá số theo whole sign&quot;">​</a></h2><ol><li>Lấy <strong>cung của Asc</strong>, đặt sign đó là house 1, đếm tiếp từng sign một.</li><li>Xác định <strong>lá số ngày hay đêm</strong> (Sun trên hay dưới chân trời).</li><li>Với mỗi hành tinh: sign, dignity, phe, retrograde, khoảng cách tới Sun.</li><li>Tính <strong>aspect theo sign</strong> (đếm sign) và ghi chú độ lệch thực tế nếu có.</li><li>Tìm <strong>chủ house</strong> của các house quan tâm, xem chủ đứng ở house nào, có nhìn thấy house của mình không.</li><li>Xếp <strong>hành tinh angular nhất</strong> theo khoảng cách (độ) tới 4 góc.</li><li>Tổng hợp theo nguyên tắc cộng dồn: yếu tố hỗ trợ so với yếu tố cản trở.</li></ol><hr><h2 id="_8-đieu-can-kiem-chung" tabindex="-1">8. Điều cần kiểm chứng <a class="header-anchor" href="#_8-đieu-can-kiem-chung" aria-label="Permalink to &quot;8. Điều cần kiểm chứng&quot;">​</a></h2><ul><li>Độ của Asc (≈ 26° Libra), MC (≈ 26° Cancer), Dsc, IC là <strong>ước lượng từ hình</strong>. Nếu có số chính xác, hãy thay vào.</li><li>Phần mềm ghi hầu hết hành tinh là &quot;peregrine&quot;, nhiều khả năng chỉ tính domicile và exaltation. Đối chiếu bảng triplicity, bound, decan trong sách.</li><li>Cách sách của Demetra George xử lý aspect theo sign và angularity theo house hay theo độ.</li><li>Phần lịch sử các hệ house và quy tắc &quot;chủ house nhìn thấy house&quot; là kiến thức chung mình biết, chưa kiểm chứng với nguồn.</li><li>Tất cả chỉ là <strong>xu hướng</strong> theo cách đọc truyền thống, không phải dự đoán sự kiện.</li></ul>',63)])])}const M=h(r,[["render",g]]);export{y as __pageData,M as default};
